        liquidityVault.deposit(1e18, 1e18);
        vm.stopPrank();
        vm.warp(block.timestamp + 10); // Increase time by 10 seconds

        // Trigger external rewards accumulation
        vm.prank(alice);
        liquidityVault.withdraw(1e18, minTokenAmounts_, false);

